listitem.para:
authenticated = [ not
            ] ( yes | no |
            real | anon )

(matches if the user has authenticated as a
            real or anonymous user;
            yes matches both)

timespec =timespec_name{
            "entry" [ ... ]
            }

listitem.screen:
# Working hours are from Mo-Fr from 9 to 16:59, and
# on Saturdays from 9 to 12:59:
timespec = workinghours {
    "* 9-16 * * 1-5"   # or: "* 9-16 * * Mon-Fri"
    "* 9-12 * * 6"     # or: "* 9-12 * * Sat"
}

timespec = sunday { "* * * * 0" }

timespec = example {
    Wk2305-0855,Sa,Su2305-1655
    Wk0905-2255,Su1705-2255
    Any
}

section.screen:
acl rfc1918 = {
    src = 127.0.0.1
    src = 10.0.0.0/8
    src = 172.16.0.0/12
    src = 192.168.0.0/16
}

acl ipv6_any = {
    src = ::0
}

acl notsunday = {
    time = workinghours
}

acl test001 = {
    arg regex = ^.cshrc$
    authenticated = real
}

acl test002 = {
    user = root
    authenticated = real
}

acl = secure { protected = yes }
acl = any { }
acl = connect { }
acl = real { authenticated = real }
acl = anon { authenticated = anon }
acl = login { authenticated = yes }

#!../obj.darwin-9.6.0-i386/ftpd
id = spawnd {
	listen = { port = 2121 }
	spawn = {
		instances min = 1
	}
	background = no
}

id = ftpd {
	debug = NET CMD
	mavis path = ../../mavis/obj.darwin-9.6.0-i386

        mavis module = anonftp {
                userid = 100
                groupid = mail
                home = /
                root = /tmp/
                upload = /tmp/incoming/
        }
	symlinks = all
	check-uid = no
	check-gid = no
	check-perm = no
}
